-- ============================================================
-- SaaS demo database - MySQL version
-- Run this whole script in MySQL Workbench (File > Run SQL Script,
-- or select-all + Execute) to create and populate the database.
-- ============================================================

DROP DATABASE IF EXISTS saas;
CREATE DATABASE saas;
USE saas;

CREATE TABLE customers (
    customer_id          VARCHAR(10) PRIMARY KEY,
    company_name         VARCHAR(255) NOT NULL,
    industry              VARCHAR(50),
    country               VARCHAR(50),
    employee_size         INT,
    acquisition_channel   VARCHAR(50),
    signup_date           DATE,
    initial_plan          VARCHAR(20)
);

CREATE TABLE subscriptions (
    subscription_id  VARCHAR(10) PRIMARY KEY,
    customer_id      VARCHAR(10),
    plan             VARCHAR(20),
    mrr              DECIMAL(10,2),
    start_date       DATE,
    end_date         DATE NULL,
    status           VARCHAR(20),
    FOREIGN KEY (customer_id) REFERENCES customers(customer_id)
);

CREATE TABLE `usage_data` (
    id                INT AUTO_INCREMENT PRIMARY KEY,
    customer_id       VARCHAR(10),
    month             DATE,
    logins            INT,
    active_seats      INT,
    support_tickets   INT,
    nps_score         INT,
    plan_at_time      VARCHAR(20),
    FOREIGN KEY (customer_id) REFERENCES customers(customer_id)
);

CREATE TABLE payments (
    payment_id    VARCHAR(10) PRIMARY KEY,
    customer_id   VARCHAR(10),
    month         DATE,
    amount        DECIMAL(10,2),
    status        VARCHAR(20),
    FOREIGN KEY (customer_id) REFERENCES customers(customer_id)
);

